from mcp.server.fastmcp import FastMCP

server = FastMCP('mcp-probe')

@server.tool()
def echo(text: str) -> str:
    """Echo the given text."""
    return 'echo: ' + text

@server.tool()
def add(a: int, b: int) -> int:
    """Add two integers."""
    return a + b

@server.tool()
def server_info() -> dict:
    """Report the server process."""
    import os, sys
    return {'name': 'mcp-probe', 'pid': os.getpid(), 'python': sys.version.split()[0]}

server.run(transport='stdio')
